gStatusMeta=function(l){
  const op=String(lessonOperationalStatus(l)||'confirmada').toLowerCase();
  if(/cancel/.test(op))return {label:statusLabel(op),cls:'cancelled'};
  if(op==='remarcacao_solicitada'||l.remarcacaoStatus==='solicitada')return {label:'Remarcação solicitada',cls:'reschedule'};
  if(l.finalizadoEm||/conclu|realiz/.test(op))return {label:'Concluída',cls:'completed'};
  if(l.iniciadoEm||op==='em_andamento')return {label:'Em andamento',cls:'completed'};
  if(l.confirmacaoAluno==='nao_participa'&&(!l.bookingConfirmation||l.bookingConfirmation.source==='legacy_reservation'))return {label:'Resposta antiga: conferir com a Secretaria',cls:'reschedule'};
  return {label:'Confirmada',cls:'confirmed'};
};

